import {segments} from './geometry.js';
export const floorData=s=>({shapes:s.shapes,walls:s.walls,entrances:s.entrances,racks:s.racks});
export function pack(s){return {version:5,unit:'metres',name:s.name,customers:s.customers??[],rackTypes:s.rackTypes,activeFloorId:s.activeFloorId,floors:s.floors.map(f=>f.id===s.activeFloorId?{...f,...floorData(s)}:f)};}
export function unpack(doc){if(!doc||!Array.isArray(doc.floors)||!doc.floors.length)throw Error('Missing floors');const floor=doc.floors.find(f=>f.id===doc.activeFloorId);if(!floor)throw Error('Missing active floor');return {...doc,customers:doc.customers??[],...floorData(floor)};}
export function withFloors(s){if(s.version===5)return unpack(s);const id=crypto.randomUUID();return unpack({version:5,unit:'metres',name:s.name,customers:s.customers??[],rackTypes:s.rackTypes,activeFloorId:id,floors:[{id,label:'Floor 1',...floorData(s)}]});}
export function selectFloor(s,id){return unpack({...pack(s),activeFloorId:id});}
export function addFloor(s){const doc=pack(s),first=doc.floors[0],shapes=first.shapes.filter(o=>o.layer==='foundation').map(o=>({...structuredClone(o),id:crypto.randomUUID()})),floor={id:crypto.randomUUID(),label:`Floor ${doc.floors.length+1}`,shapes,walls:segments(shapes,first.walls),entrances:[],racks:[]};return unpack({...doc,activeFloorId:floor.id,floors:[...doc.floors,floor]});}
export function validFloors(s,check){try{const doc=pack(s);return doc.floors.length<=50&&doc.floors.length>0&&new Set(doc.floors.map(f=>f.id)).size===doc.floors.length&&doc.floors.every(f=>typeof f.id==='string'&&typeof f.label==='string'&&f.label.trim().length>0&&f.label.length<=80&&check({...s,...floorData(f)}));}catch{return false;}}
